//! SAME Analyze SCHEMA then TRACKED_SCHEMA/include-order policy.
use crate::{tree::SourceFile,key_policy_control::{self as kc,Control},value_schema_policy::ValueKind};
use dm_analysis::value_schemas::{Kind,Schemas};use dm_ir::SymbolId;use std::collections::HashMap;
pub struct Event{phase:u8,relative:String,offset:usize,owner:String,var:String,kind:Kind}
pub fn read_file<C:Control,T:Control<Error=C::Error>>(file:&SourceFile,events:&mut Vec<Event>,retained:&mut C,temporary:&mut T)->Result<(),C::Error>{
 kc::reserve(temporary,||file.raw().text.len().checked_mul(32)?.checked_add(8192))?;
 for(phase,name)in["SCHEMA","TRACKED_SCHEMA"].into_iter().enumerate(){retained.checkpoint()?;let text=file.marker().as_str();let mut offset=0;for line in text.split('\n'){retained.checkpoint()?;if let Some(marker)=crate::raw_marker_policy::statement_marker(text,offset,line,&[name]){let args=crate::raw_marker_policy::split_args(&text[marker.open+1..marker.close]);if let[owner,var,value,..]=args.as_slice(){if let Some(kind)=crate::value_schema_policy::kind_of(value){let kind=match kind{ValueKind::Path(path)=>{kc::reserve(retained,||path.capacity().checked_add(64))?;Kind::Path(path)},ValueKind::Msg=>Kind::Msg,ValueKind::Plain=>Kind::Plain,ValueKind::Many=>Kind::Many,ValueKind::Any=>Kind::Any};kc::row(retained,events)?;events.push(Event{phase:phase as u8,relative:kc::own(retained,&file.rel)?,offset,owner:kc::own(retained,owner.trim())?,var:kc::own(retained,var.trim())?,kind});}}}offset=offset.checked_add(line.len()).and_then(|n|n.checked_add(1)).ok_or_else(||retained.overflow())?;}}
 retained.checkpoint()
}
pub fn order_from_original<C:Control>(manifest:crate::captured_untyped::ManifestRead<'_>,work:&mut C)->Result<HashMap<String,usize>,C::Error>where C::Error:From<String>{use crate::captured_untyped::ManifestRead;match manifest{ManifestRead::CompiledOriginalBytes(bytes)|ManifestRead::OriginalBytes(bytes)=>match std::str::from_utf8(bytes){Ok(text)=>crate::raw_marker_policy::dme_include_order_controlled(text,false,work),Err(_)=>Ok(HashMap::new())},ManifestRead::ProvenUnavailable=>Ok(HashMap::new()),ManifestRead::Compiled=>Err("complete untyped schemas require actual original manifest bytes or authenticated absence".to_owned().into())}}
pub fn finish<C:Control>(mut events:Vec<Event>,order:&HashMap<String,usize>,work:&mut C)->Result<Schemas,C::Error>{dm_analysis::checker_order::sort_policy_data(&mut events,&mut|a,b|->Result<std::cmp::Ordering,C::Error>{work.checkpoint()?;Ok((a.phase,order.get(&a.relative).copied().unwrap_or(usize::MAX),a.relative.as_str(),a.offset).cmp(&(b.phase,order.get(&b.relative).copied().unwrap_or(usize::MAX),b.relative.as_str(),b.offset)))})?;let mut schemas=Schemas::default();for event in events{work.checkpoint()?;kc::reserve(work,||Some(2048))?;schemas.insert_policy_kind(SymbolId::of(&event.owner),SymbolId::of(&event.var),event.kind);}work.checkpoint()?;Ok(schemas)}
